 if(!lensAmbiguousPlates){const outputs=new Map();for(let code=0;code<15625;code++){let n=code,v=[];for(let i=0;i<6;i++){v.push(n%5);n=n/5|0}for(let k=0;k<6;k++){const out=blur(v,k),key=out.join(',');const record=outputs.get(key);if(record)record.mask|=1<<k;else outputs.set(key,{out,mask:1<<k})}}lensAmbiguousPlates=[...outputs.values()].filter(x=>(x.mask&(x.mask-1))&&new Set(x.out).size>=3)}
 let stage=0,kernel=0,observed=[],reconstruction=Array(6).fill(0),chosen=0,energy=8,probe=Array(6).fill(0),sensor=0,history=[],credits=3;
 function setup(){const plate=lensAmbiguousPlates[rnd(lensAmbiguousPlates.length)];observed=plate.out.slice();kernel=shuffle(kernels.map((_,i)=>i).filter(i=>plate.mask>>i&1))[0];energy=8;probe=Array(6).fill(0);sensor=rnd(6);history=[];reconstruction=Array(6).fill(0);chosen=0}setup();
