engines['invisible-ink']=()=>{let stage=0,evidence=[],notes=[],charges=5,channel=0,marked=new Set();function setup(){const genuine=shuffle(Array.from({length:9},(_,i)=>i)).slice(0,2);evidence=Array.from({length:9},(_,i)=>genuine.includes(i)?7:rnd(7));const activeRows=[...new Set(genuine.map(i=>i/3|0))];if(activeRows.length===2){const easy=activeRows[rnd(2)];for(let col=0;col<3;col++){const i=easy*3+col;if(!genuine.includes(i))evidence[i]=[0,1,2,4][rnd(4)]}}notes=Array.from({length:9},()=>[null,null,null]);charges=5;marked.clear()}setup();function render(){clear();meter(`Sheet ${stage+1}/3 · ${charges} strip scans`);p('Manifest genuine parcels per row: '+[0,1,2].map(r=>evidence.slice(r*3,r*3+3).filter(x=>x===7).length).join(' · '));const a=actions();['UV','Heat','Pressure'].forEach((n,k)=>btn(n,()=>{channel=k;render()},a,{selected:channel===k}));p('Evidence shown as UV / heat / pressure: 1 present, 0 absent, ? unobserved.');const g=grid(3);notes.forEach((v,i)=>cell(`${String.fromCharCode(65+i%3)}${1+(i/3|0)} ${v.map(x=>x===null?'?':x).join('/')}`,()=>{marked.has(i)?marked.delete(i):marked.size<2&&marked.add(i);render()},g,marked.has(i)));const scan=(indices,label)=>{if(charges<1)return finish(false,'No strip scans remain.');indices.forEach(i=>notes[i][channel]=(evidence[i]>>channel)&1);charges--;render();status(`${label} exposed in ${['UV','heat','pressure'][channel]}.`);if(charges<0)finish(false,'The sheet exhausted its exposure budget.')};const b=actions();for(let r=0;r<3;r++)btn('Scan row '+(r+1),()=>scan([r*3,r*3+1,r*3+2],'Row '+(r+1)),b);for(let c=0;c<3;c++)btn('Scan column '+String.fromCharCode(65+c),()=>scan([c,c+3,c+6],'Column '+String.fromCharCode(65+c)),b);btn('Certify two parcels',()=>{if(marked.size!==2)return status('Mark exactly two parcels.');if([...marked].every(i=>evidence[i]===7)){if(++stage===3)return finish(true,'Three sheets authenticated.');setup();render();status('Manifest certified. New sheet.')}else finish(false,'The selected parcels do not both carry all evidence channels.')})}return{render}};
